// SOLO PRUEBA. Convierte "1".."6" en una fila igual a la que daría el
// formulario de Google. Sustituir por el Google Sheets Trigger en producción.
const TZ = 'America/Lima';
const hoy = DateTime.now().setZone(TZ);
const correo = 'flum2.carlos.ramirez@gmail.com';   // todo el correo dummy va al propio buzón
const n = String($json.chatInput ?? '1').trim().charAt(0);

const casos = {
  '1': { caso: '1 · completa, dentro de corte',
         Docente: 'Ana Quispe Mamani', Motivo: 'Licencia médica',
         Evidencia: 'Certificado médico del centro de salud, 2 días de descanso, folio 88231.',
         'Fecha de la incidencia': hoy.toISODate() },
  '2': { caso: '2 · completa, fuera de corte (va a jefatura)',
         Docente: 'Luis Cárdenas Rojas', Motivo: 'Comisión de servicio',
         Evidencia: 'Oficio 145-2026-DIR autorizando representación institucional.',
         'Fecha de la incidencia': hoy.minus({ months: 1 }).toISODate() },
  '3': { caso: '3 · incompleta (sin motivo)',
         Docente: 'Rosa Huamán Ticona', Motivo: '',
         Evidencia: '', 'Fecha de la incidencia': hoy.toISODate() },
  '4': { caso: '4 · ambigua (debe ir a revisión humana)',
         Docente: 'Pedro Salas Vega', Motivo: 'Asunto personal delicado',
         Evidencia: 'Prefiero explicarlo en persona con la dirección.',
         'Fecha de la incidencia': hoy.toISODate() },
  '5': { caso: '5 · válida pero sin asistentes disponibles',
         Docente: 'Carmen Loayza Pinto', Motivo: 'Capacitación institucional',
         Evidencia: 'Constancia de asistencia al taller de evaluación formativa.',
         'Fecha de la incidencia': hoy.toISODate(), forzar_sin_asistente: true },
  '6': { caso: '6 · rechazada por validación',
         Docente: 'Jorge Ríos Alarcón', Motivo: 'Licencia médica',
         Evidencia: 'No tengo certificado, estuve de viaje familiar esos días.',
         'Fecha de la incidencia': hoy.minus({ months: 8 }).toISODate() },
};

const c = casos[n] || casos['1'];
return [{ json: { ...c, 'Correo del solicitante': correo } }];

// Día de corte de planilla. Único sitio donde se define.
const TZ = 'America/Lima';
const DIA_CORTE = 20;

return $input.all().map((it, i) => {
  const d = it.json;
  const hoy = DateTime.now().setZone(TZ);
  const inc = DateTime.fromISO(String(d['Fecha de la incidencia']), { zone: TZ });

  // Dentro de corte = la incidencia es del periodo de planilla en curso
  // y hoy todavía no pasa el día de corte. No lo declara el solicitante.
  const mismoPeriodo = inc.isValid && inc.hasSame(hoy, 'month') && inc.hasSame(hoy, 'year');
  const dentro_de_corte = Boolean(mismoPeriodo && hoy.day <= DIA_CORTE);

  // Código único por ejecución: no puede colisionar y arrastrar el update
  // de otro docente, como pasaba con el Math.random() de 4 dígitos.
  const codigo = `REG-${hoy.toFormat('yyyyLLdd')}-${$execution.id}-${String(i + 1).padStart(2, '0')}`;

  return { json: {
    ...d,
    codigo_seguimiento: codigo,
    docente: d['Docente'],
    motivo: d['Motivo'],
    evidencia: d['Evidencia'] ?? '',
    correo_solicitante: d['Correo del solicitante'],
    fecha_incidencia: inc.isValid ? inc.toISODate() : '',
    dentro_de_corte,
    estado: 'Registrada',
    fecha_registro: hoy.toISO(),
  }};
});

