// Campos esperados en la tabla Asistentes: nombre, disponible (checkbox),
// carga (número), correo. Si cambian, se cambia aquí y en el filtro de P03.
const reg = $('P01.1.1 Preparar Registro').first().json;

// SOLO PRUEBA: el caso 5 fuerza el escenario "no hay nadie libre".
const forzado = $('D00 Caso dummy').first().json.forzar_sin_asistente === true;

const filas = forzado ? [] : $input.all().map(i => i.json).filter(a => a && a.nombre);

// Cierra ante la duda: sólo cuenta quien está marcado disponible de forma
// explícita. Antes, un campo ausente dejaba pasar a todo el mundo.
const disponibles = filas.filter(a => a.disponible === true || a.disponible === 'true' || a.disponible === 1);

if (disponibles.length === 0) {
  return [{ json: { codigo_seguimiento: reg.codigo_seguimiento, asistente_encontrado: false,
                    asistentes_evaluados: filas.length } }];
}

disponibles.sort((a, b) => (Number(a.carga) || 0) - (Number(b.carga) || 0));
const elegido = disponibles[0];

return [{ json: {
  codigo_seguimiento: reg.codigo_seguimiento,
  asistente_encontrado: true,
  asistente: elegido.nombre,
  asistente_correo: elegido.correo || '',
  asistente_carga: Number(elegido.carga) || 0,
  asistentes_evaluados: filas.length,
}}];

